cat > ../fix.mjs <<'EOF'
import fs from 'fs';import path from 'path';
const re=/<app-(?:fancy|status)-pill(?:"[^"]*"|'[^']*'|[^>"'])*>/g;
function walk(d){for(const e of fs.readdirSync(d,{withFileTypes:true})){const p=path.join(d,e.name);if(e.isDirectory())walk(p);else if(/\.(ts|html)$/.test(p)){let s=fs.readFileSync(p,'utf8');const n=s.replace(re,m=>m.replace(/\[disableTooltip\]/g,'[hideHint]').replace(/(\s)disableTooltip(?=[\s/>])/g,'$1hideHint'));if(n!==s)fs.writeFileSync(p,n);}}}
walk('src');
EOF
